window.VO = [{"id":"n01","text":"Read this in your mother's voice.","at":0.24,"t0":0.12,"t1":1.775},{"id":"n02","text":"You heard her, didn't you? And I wrote that in English. How many of you heard English?","at":6.15,"t0":3.075,"t1":7.53},{"id":"n03","text":"I've got four of these, and one won't work.","at":15.86,"t0":7.93,"t1":10.085},{"id":"n04","text":"Now she's walked in.","at":20.97,"t0":10.485,"t1":11.7},{"id":"n05","text":"You just checked your back, didn't you?","at":25.9,"t0":12.95,"t1":14.51},{"id":"n06","text":"Now you've embarrassed her in front of guests.","at":29.86,"t0":14.93,"t1":16.96},{"id":"n07","text":"You pay rent, and that still goes straight to your stomach.","at":37.02,"t0":18.51,"t1":21.245},{"id":"n08","text":"Last one.","at":43.49,"t0":21.745,"t1":22.58},{"id":"n09","text":"Strange, isn't it? Like someone doing an impression of her.","at":49.76,"t0":24.88,"t1":28.15},{"id":"n10","text":"Your brain built that voice out of everything she's ever said to you.","at":57.14,"t0":28.57,"t1":32.04},{"id":"n11","text":"So how many times has she actually said that one?","at":64.68,"t0":32.34,"t1":35.155},{"id":"n12","text":"And how many times has she said this?","at":71.91,"t0":35.955,"t1":37.945},{"id":"n13","text":"It's the same sentence.","at":79.39,"t0":39.695,"t1":41.005},{"id":"n14","text":"Some of you can only hear it this way now.","at":83.71,"t0":41.855,"t1":43.98},{"id":"n15","text":"The rest of you still have the original.","at":89.16,"t0":44.58,"t1":46.665},{"id":"n16","text":"Have you got one recording of her asking?","at":93.93,"t0":46.965,"t1":49.07}];
